def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts: dict[str, list] = {}
    undo_stack: list[tuple] = []
    rejected: list[int] = []

    def amount(token: str):
        if not token or not token.isdigit():
            return None
        return int(token)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False
        if verb == "open" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if n is not None and name not in accounts:
                accounts[name] = [n, False]
                undo_stack.append(("open", name))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if n is not None and n > 0 and name in accounts:
                accounts[name][0] += n
                undo_stack.append(("deposit", name, n))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if (
                n is not None
                and n > 0
                and name in accounts
                and not accounts[name][1]
                and accounts[name][0] >= n
            ):
                accounts[name][0] -= n
                undo_stack.append(("withdraw", name, n))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            src, dst, n = parts[1], parts[2], amount(parts[3])
            if (
                n is not None
                and n > 0
                and src != dst
                and src in accounts
                and dst in accounts
                and not accounts[src][1]
                and accounts[src][0] >= n
            ):
                accounts[src][0] -= n
                accounts[dst][0] += n
                undo_stack.append(("transfer", src, dst, n))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            name = parts[1]
            if name in accounts and not accounts[name][1]:
                accounts[name][1] = True
                undo_stack.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            name = parts[1]
            if name in accounts and accounts[name][1]:
                accounts[name][1] = False
                undo_stack.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(parts) == 1 and undo_stack:
            kind = undo_stack.pop()
            if kind[0] == "open":
                del accounts[kind[1]]
            elif kind[0] == "deposit":
                accounts[kind[1]][0] -= kind[2]
            elif kind[0] == "withdraw":
                accounts[kind[1]][0] += kind[2]
            elif kind[0] == "transfer":
                accounts[kind[1]][0] += kind[3]
                accounts[kind[2]][0] -= kind[3]
            elif kind[0] == "freeze":
                accounts[kind[1]][1] = False
            elif kind[0] == "unfreeze":
                accounts[kind[1]][1] = True
            ok = True
        if not ok:
            rejected.append(i)

    return {name: state[0] for name, state in accounts.items()}, rejected
